#!/usr/bin/env node
/**
 * Emit declarations for the inlined workspace packages.
 *
 * tsup's `noExternal` inlines the JavaScript of @runback/{redact,schema,policy,
 * replay}, so the published package needs no access to this repo at runtime.
 * Declarations are generated by a separate bundler that does not honour it: the
 * emitted .d.ts kept `import ... from "@runback/redact"` — bare specifiers for
 * packages that are private and 404 on npm. So the runtime worked and
 * `tsc --strict` did not, and every TypeScript consumer got TS2307 on four
 * modules they had no way to install.
 *
 * `dts: { resolve: [...] }` rewrites those to relative specifiers (./redact,
 * ./events, ./cassette) but never emits the targets, which trades one broken
 * form for another. `dts: { resolve: true }` fails outright on our sources.
 *
 * So: let tsc — which handles these files without complaint — emit the real
 * declarations, and place them at exactly the relative paths the chunk already
 * imports. Cross-package bare specifiers inside that tree are rewritten to
 * relative paths for the same reason.
 *
 * The end-to-end check that matters is not this script: it is `npm pack` +
 * `tsc --strict` against the tarball, which is what a consumer actually runs.
 */
import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync, existsSync, rmSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const SDK = dirname(dirname(fileURLToPath(import.meta.url)));
const REPO = dirname(dirname(SDK));
const DIST = join(SDK, "dist");
const TREE = join(DIST, "_workspace-types");

/** Module specifier the built chunk imports → the source file behind it. */
const SHIMS = {
  redact: "packages/redact/src/index.ts",
  events: "packages/schema/src/events.ts",
  // The chunk imports ReexecuteController/OnMiss/HybridOutcome under the
  // name "./cassette", but they are declared in hybrid.ts — emit both and
  // re-export the pair, or the shim resolves to a module missing them.
  cassette: "packages/replay/src/cassette.ts",
  hybrid: "packages/replay/src/hybrid.ts",
};

if (existsSync(TREE)) rmSync(TREE, { recursive: true, force: true });

execFileSync(
  "npx",
  [
    "tsc",
    ...Object.values(SHIMS).map((p) => join(REPO, p)),
    "--declaration", "--emitDeclarationOnly", "--skipLibCheck",
    "--target", "es2022", "--module", "esnext", "--moduleResolution", "bundler",
    "--outDir", TREE,
  ],
  { cwd: REPO, stdio: "inherit" }
);

// tsc preserves the source layout under the common root, so paths mirror the
// repo. Point each shim at its emitted declaration.
// One shim may need to cover several source modules: the bundler collapsed the
// replay package's cassette and hybrid types under the single name "./cassette".
const EMITTED = {
  redact: ["./_workspace-types/redact/src/index"],
  events: ["./_workspace-types/schema/src/events"],
  cassette: [
    "./_workspace-types/replay/src/cassette",
    "./_workspace-types/replay/src/hybrid",
  ],
};

for (const [name, targets] of Object.entries(EMITTED)) {
  for (const ext of ["d.ts", "d.cts"]) {
    writeFileSync(
      join(DIST, `${name}.${ext}`),
      targets.map((t) => `export * from "${t}";`).join("\n") + "\n"
    );
  }
}

// A declaration inside the emitted tree may still reference a sibling package
// by its bare name; rewrite those the same way, or the consumer hits the exact
// TS2307 this script exists to remove.
const CROSS = [
  [/from "@runback\/schema"/g, 'from "../../schema/src/events"'],
  [/from "@runback\/redact"/g, 'from "../../redact/src/index"'],
];
const files = execFileSync("find", [TREE, "-name", "*.d.ts"], { encoding: "utf8" })
  .split("\n")
  .filter(Boolean);
for (const f of files) {
  const before = readFileSync(f, "utf8");
  let after = before;
  for (const [re, to] of CROSS) after = after.replace(re, to);
  if (after !== before) writeFileSync(f, after);
}

console.log(`workspace declarations emitted for ${Object.keys(SHIMS).join(", ")}`);
